#!/usr/bin/env python3
"""Generate hxprobe/src/names.rs from schema/types.json.

types.json maps object type id (decimal string) -> name or null. Null names
are skipped. The output holds TYPE_COUNT, a TYPES table sorted by id, the
lookup functions and their tests, so regenerating never loses code.

Usage: python3 tools/gen_names.py   (then run `cargo fmt` in hxprobe/)
"""
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
SRC = ROOT / "schema" / "types.json"
OUT = ROOT / "hxprobe" / "src" / "names.rs"

HEAD = """\
// @generated by tools/gen_names.py from schema/types.json. Do not edit by
// hand: change the generator or the JSON and rerun it.

//! Object type id -> name.

/// Number of named object types in [`TYPES`].
pub const TYPE_COUNT: usize = {count};

/// `(type id, name)`, strictly sorted by id.
pub static TYPES: [(u16, &str); TYPE_COUNT] = [
"""

TAIL = """\
];

/// Name of object type `id`, if known.
pub fn type_name(id: u16) -> Option<&'static str> {
    TYPES
        .binary_search_by_key(&id, |&(i, _)| i)
        .ok()
        .map(|i| TYPES[i].1)
}

/// Parse a type given as a name (case-insensitive), a `0x..` hex id or a
/// decimal id. Numeric ids are accepted even when the type has no name.
pub fn type_id(s: &str) -> Option<u16> {
    let s = s.trim();
    if let Some(hex) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        return u16::from_str_radix(hex, 16).ok();
    }
    if !s.is_empty() && s.bytes().all(|b| b.is_ascii_digit()) {
        return s.parse().ok();
    }
    TYPES
        .iter()
        .find(|(_, n)| n.eq_ignore_ascii_case(s))
        .map(|&(i, _)| i)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_names() {
        assert_eq!(type_name(0xc9), Some("MessageHeader"));
        assert_eq!(type_name(0xca), Some("MessageData"));
        assert_eq!(type_id("recipient"), Some(0xd2));
        assert_eq!(type_id("Recipient"), Some(0xd2));
        assert_eq!(type_id("0xd2"), Some(0xd2));
        assert_eq!(type_id("210"), Some(0xd2));
    }

    #[test]
    fn unknown_is_none() {
        // id 1 is present in types.json with a null name.
        assert_eq!(type_name(1), None);
        assert_eq!(type_name(u16::MAX), None);
        assert_eq!(type_id("NoSuchType"), None);
        assert_eq!(type_id(""), None);
        assert_eq!(type_id("0xzz"), None);
        assert_eq!(type_id("70000"), None);
    }

    #[test]
    fn table_sorted_and_complete() {
        assert!(TYPES.windows(2).all(|w| w[0].0 < w[1].0));
        assert_eq!(TYPE_COUNT, 449);
        assert_eq!(TYPES.len(), TYPE_COUNT);
    }
}
"""


def main():
    raw = json.loads(SRC.read_text(encoding="utf-8"))
    rows = sorted((int(k), v) for k, v in raw.items() if v is not None)
    for i, name in rows:
        if not 0 <= i <= 0xFFFF:
            raise SystemExit(f"type id {i} does not fit u16")
        if not name.isidentifier():
            raise SystemExit(f"unexpected type name {name!r}")
    body = "".join(f'    (0x{i:x}, "{name}"),\n' for i, name in rows)
    OUT.write_text(HEAD.format(count=len(rows)) + body + TAIL, encoding="utf-8")
    print(f"wrote {OUT.relative_to(ROOT)}: {len(rows)} types")


if __name__ == "__main__":
    main()
